import { chromium } from 'playwright';import fs from 'fs';import path from 'path';
const BASE='https://www.statesideqm.com',THEME='158900125851',key=process.env.KEY,label=process.env.LABEL,route=process.env.ROUTE,OUT='sep18-sg-fetch-scope-'+key;fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true});
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});await c.addInitScript(()=>{window.__sqLcp=0;try{new PerformanceObserver(l=>{for(const e of l.getEntries())window.__sqLcp=Math.max(window.__sqLcp,e.startTime||0)}).observe({type:'largest-contentful-paint',buffered:true})}catch{}});
const p=await c.newPage();p.setDefaultNavigationTimeout(70000);const req=[];p.on('request',r=>{if(r.resourceType()==='fetch'||r.resourceType()==='xhr')req.push(r.url())});
const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);let resp=null,error=null;try{resp=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(5500)}catch(e){error=String(e?.message||e)}
const row=await p.evaluate(({label,route,req,themeId})=>{const n=performance.getEntriesByType('navigation')[0],f=performance.getEntriesByName('first-contentful-paint')[0],view=document.querySelector('[data-sqsg-view]');const cards=[...(view?.querySelectorAll('.sqsg-card')||[])].map(a=>({label:(a.querySelector('strong')?.textContent||'').replace(/\s+/g,' ').trim(),meta:(a.querySelector('small')?.textContent||'').replace(/\s+/g,' ').trim(),href:a.getAttribute('href')||''}));const pj=req.filter(u=>u.includes('/products.json'));return{label,route,theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')},ttfbMs:Math.round(n?.responseStart||0),loadMs:Math.round(n?.loadEventEnd||0),fcpMs:Math.round(f?.startTime||0),lcpMs:Math.round(window.__sqLcp||0),productJson:pj,productJsonCount:pj.length,uniqueProductJsonCount:new Set(pj).size,cards,cardCount:cards.length,viewText:(view?.innerText||'').replace(/\s+/g,' ').trim().slice(0,1600),viewProducts:view?.querySelectorAll('.sqsg-product').length||0,uniformAuthority:view?.dataset.sqUniformAuthority||'',equipmentAuthority:view?.dataset.sqEquipmentAuthority||'',tacticalAuthority:view?.dataset.sqTacticalAuthority||'',brokenImages:[...document.images].filter(i=>i.complete&&i.naturalWidth===0).length,previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {label,route,req,themeId:THEME});row.http=resp?.status()??null;row.error=error;fs.writeFileSync(path.join(OUT,'result.json'),JSON.stringify(row,null,2));await p.screenshot({path:path.join(OUT,'screenshots','page.png'),fullPage:false}).catch(()=>{});console.log('SGFETCHSCOPE',JSON.stringify(row));if(row.http!==200||!row.previewOk||error||row.brokenImages||(!row.viewProducts&&!row.cardCount))process.exitCode=2;await c.close();await b.close();